def find_m_max():
    best_m = 0
    for k in range(3, 2026):
        x_base = 2025 // k
        r = 2025 % k
        x = [x_base] * k
        # Place the extra 1s in the middle to maximize the sums of products
        for i in range(r):
            x[k // 2 + i] += 1
            # If it goes out of bounds, wrap around (should not happen for k >= 3)
            if k // 2 + i >= k:
                x[i] += 1

        m_odd = 0
        for i in range(0, k - 2, 2):
            m_odd += x[i] * x[i+1] * x[i+2]

        m_even = 0
        for i in range(1, k - 2, 2):
            m_even += x[i] * x[i+1] * x[i+2]

        m = max(m_odd, m_even)
        if m > best_m:
            best_m = m
    return best_m

print(find_m_max())
